# ---- embedded candidate algorithms -----------------------------------------
def gen_random(n, seed):
    import random
    r = random.Random(seed)
    return [r.randrange(n * 10) for _ in range(n)]


def gen_nearly_sorted(n, seed):
    import random
    r = random.Random(seed)
    a = list(range(n))
    for _ in range(max(1, n // 100)):
        i = r.randrange(n - 1)
        a[i], a[i + 1] = a[i + 1], a[i]
    return a


def gen_reversed(n, seed):
    return list(range(n, 0, -1))


def gen_few_unique(n, seed):
    import random
    r = random.Random(seed)
    return [r.randrange(8) for _ in range(n)]


def insertion_sort(a):
    a = list(a)
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a


def _merge(left, right):
    out = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            out.append(left[i]); i += 1
        else:
            out.append(right[j]); j += 1
    out.extend(left[i:])
    out.extend(right[j:])
    return out


def merge_sort(a):
    a = list(a)
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    return _merge(merge_sort(a[:mid]), merge_sort(a[mid:]))


def quick_sort(a):
    a = list(a)
    stack = [(0, len(a) - 1)]
    while stack:
        lo, hi = stack.pop()
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < a[lo]:
                a[lo], a[mid] = a[mid], a[lo]
            if a[hi] < a[lo]:
                a[lo], a[hi] = a[hi], a[lo]
            if a[hi] < a[mid]:
                a[mid], a[hi] = a[hi], a[mid]
            pivot = a[mid]
            i, j = lo - 1, hi + 1
            while True:
                i += 1
                while a[i] < pivot:
                    i += 1
                j -= 1
                while a[j] > pivot:
                    j -= 1
                if i >= j:
                    break
                a[i], a[j] = a[j], a[i]
            if j - lo < hi - (j + 1):
                stack.append((j + 1, hi))
                hi = j
            else:
                stack.append((lo, j))
                lo = j + 1
    return a


def heap_sort(a):
    a = list(a)
    n = len(a)

    def sift(start, end):
        root = start
        while 2 * root + 1 <= end:
            child = 2 * root + 1
            if child + 1 <= end and a[child] < a[child + 1]:
                child += 1
            if a[root] < a[child]:
                a[root], a[child] = a[child], a[root]
                root = child
            else:
                return

    for s in range(n // 2 - 1, -1, -1):
        sift(s, n - 1)
    for e in range(n - 1, 0, -1):
        a[0], a[e] = a[e], a[0]
        sift(0, e - 1)
    return a


ALGORITHMS = {"insertion_sort": insertion_sort, "merge_sort": merge_sort, "quick_sort": quick_sort, "heap_sort": heap_sort}
GENERATORS = {"random": gen_random, "nearly_sorted": gen_nearly_sorted, "reversed": gen_reversed, "few_unique": gen_few_unique}


def main():
    rows = []
    for alg_name in CONFIG["algorithms"]:
        fn = ALGORITHMS[alg_name]
        for regime in CONFIG["regimes"]:
            gen = GENERATORS[regime]
            for n in CONFIG["sizes"]:
                times = []
                for t in range(CONFIG["trials"]):
                    data = gen(n, CONFIG["seed"] + t)
                    expected = sorted(data)
                    t0 = time.perf_counter()
                    out = fn(data)
                    dt = time.perf_counter() - t0
                    if out != expected:
                        json.dump({"error": "INCORRECT OUTPUT: " + alg_name}, open("result.json", "w"))
                        print("CORRECTNESS FAILURE:", alg_name)
                        sys.exit(2)
                    times.append(dt)
                rows.append({
                    "algorithm": alg_name, "regime": regime, "n": n,
                    "mean_s": statistics.fmean(times),
                    "stdev_s": statistics.pstdev(times) if len(times) > 1 else 0.0,
                    "trials": CONFIG["trials"],
                })
    with open("result.json", "w") as f:
        json.dump({"rows": rows}, f, indent=2)
    print("OK", len(rows), "measurements")


main()
